INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 26, 'theory', 'Quiz: OLTP and OLAP');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 0, 'How do OLAP queries differ from OLTP queries?', '["They change one row at a time by index in milliseconds", "They read many rows but few columns, and roll them up into a small result", "They don''t use SQL", "They work with a single table without joins"]', 1, 'OLTP is short pinpoint operations on rows, OLAP is a scan of millions of rows and aggregation; that is why they need different storage.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 1, 'Why do you have to limit analytics on the primary database?', '["SQL forbids aggregates", "Analytical data can''t be stored in tables", "The database can''t do GROUP BY", "A heavy scan pushes hot pages out of memory and takes disk, and long transactions block version cleanup"]', 3, 'A read replica is enough for small reports; for heavy loads you build a separate warehouse.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 2, 'What is the star schema?', '["A fact table in the center with dimension tables around it", "A single table without keys", "A dependency graph between indexes", "A ring of nodes with consistent hashing"]', 0, 'Facts are events with numbers, dimensions are descriptive reference tables; denormalizing dimensions reduces the number of joins.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 3, 'Why must rerunning a load be idempotent?', '["So that the load runs faster", "So that indexes are not needed", "So that repeating the same batch does not duplicate rows and any period can be recomputed", "So that data is stored in one file"]', 2, 'You replace the partition or insert with a key check: then a failure in the middle and a rerun are safe.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 26, 4, 'What is change data capture (CDC) for?', '["For encrypting backups", "To read the database log and pass changes as an event stream with almost no load on the tables", "For choosing an index", "For closing long transactions"]', 1, 'Events may arrive again, so per-key order is preserved and processing is made idempotent.');
